fn run() -> Result<bool> {
    let factory = crate::clap_app::CommandFactory::new();
    let app = factory.app()?;

    if app.matches.is_present("cache") {
        run_cache_subcommand(&app.matches)?;
        Ok(true)
    } else {
            let config = factory.config(&app)?;

            if app.matches.is_present("list-languages") {
                list_languages(&config)?;

                Ok(true)
            } else if app.matches.is_present("list-themes") {
                list_themes(&config)?;

                Ok(true)
            } else if app.matches.is_present("config-file") {
                println!("{}", config_file_path().to_string_lossy());

